// Task: An asynchronous job the context server hands to the LLM server.
type Task struct {
	ID          string     `json:"id"`
	Kind        TaskKind   `json:"kind"`
	Project     string     `json:"project"`
	Input       TaskInput  `json:"input"`
	State       TaskState  `json:"state"`
	Attempts    int64      `json:"attempts"`
	Result      TaskResult `json:"result"`
	Error       string     `json:"error"`
	RequestedBy Author     `json:"requested_by"`
	RequestedAt string     `json:"requested_at"`
	FinishedAt  *string    `json:"finished_at"`
}

func (v *Task) UnmarshalJSON(data []byte) error {
	type plain Task
	var w struct {
		plain
		Input  json.RawMessage `json:"input"`
		Result json.RawMessage `json:"result"`
	}
	w.plain = plain{}
	if err := json.Unmarshal(data, &w); err != nil {
		return err
	}
	*v = Task(w.plain)
	var err error
	if v.Input, err = decodeOne(w.Input, DecodeTaskInput); err != nil {
		return fmt.Errorf("Task.input: %w", err)
	}
	if v.Result, err = decodeOne(w.Result, DecodeTaskResult); err != nil {
		return fmt.Errorf("Task.result: %w", err)
	}
	return nil
}

